INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Software-Update immer für Sicherheitslücken gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch Funktionen verbessern"}, {"text": "Ja", "correct": false, "because": "Nicht nur Sicherheitsfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel, wenn ich ein System aktualisiere?', 3, '[{"text": "Schließen von Schwachstellen", "correct": true, "because": "Verhindert Angriffe"}, {"text": "Maximale Komplexität", "correct": false, "because": "Gegenteil des Ziels"}, {"text": "Manuelle Installation", "correct": false, "because": "Automatisierung bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen ein Update effektiv?', 5, '[{"text": "Sicherheitsverbesserung", "correct": true, "because": "Schützt vor Exploits"}, {"text": "Kompatibilitätsprüfung", "correct": true, "because": "Vermeidet Systemfehler"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nur für Download relevant"}, {"text": "Grafische Überarbeitung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Updates beheben oft Sicherheitslücken. b) Sie sind immer optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist bei Sicherheit kritisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung von Software-Updates?', 4, '[{"text": "Testumgebung", "correct": false, "because": "Vermeidet Produktionsfehler"}, {"text": "Priorisierung", "correct": false, "because": "Kritische Updates zuerst"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Updates"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Updates immer einen Neustart erfordern?', 2, '[{"text": "Nein", "correct": true, "because": "Manche sind hotfix-fähig"}, {"text": "Ja", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist für die Auswahl eines Updates entscheidend?', 3, '[{"text": "Relevanz für Schwachstellen", "correct": true, "because": "Sichert Schutz"}, {"text": "Schnelle Verfügbarkeit", "correct": false, "because": "Qualität wichtiger"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern ein effektives Update-Management?', 5, '[{"text": "Automatische Verteilung", "correct": true, "because": "Vereinfacht Rollout"}, {"text": "Vorabtests", "correct": true, "because": "Vermeiden Fehler"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Downloads", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Updates verbessern die Sicherheit. b) Sie verlangsamen immer Systeme. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Update-Management?', 4, '[{"text": "Testsystem", "correct": false, "because": "Prüft Kompatibilität"}, {"text": "Rückfallplan", "correct": false, "because": "Sichert Wiederherstellung"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Updates"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Updates nur für Betriebssysteme?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Anwendungen relevant"}, {"text": "Ja", "correct": false, "because": "Breiter Anwendungsbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Systeme profitieren von regelmäßigen Updates?', 4, '[{"text": "Server", "correct": true, "because": "Schützen vor Angriffen"}, {"text": "Workstations", "correct": true, "because": "Verbessern Stabilität"}, {"text": "Offline-Medien", "correct": false, "because": "Nicht updatebar"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Updates immer riskant sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Risiken mit Tests minimierbar"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Verwaltung von Updates?', 3, '[{"text": "Kritische Sicherheitsupdates", "correct": true, "because": "Schützen zuerst"}, {"text": "Visuelle Änderungen", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Freigaben", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Updates können Fehler beheben. b) Sie erhöhen immer die Komplexität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein gutes Update-Management?', 5, '[{"text": "Erhöhte Sicherheit", "correct": true, "because": "Schließt Schwachstellen"}, {"text": "Systemstabilität", "correct": true, "because": "Behebt Fehler"}, {"text": "Hohe Downloadgeschwindigkeit", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Anwendung von Updates unwichtig?', 3, '[{"text": "Zeitplanung", "correct": false, "because": "Minimiert Ausfallzeiten"}, {"text": "Kompatibilität", "correct": false, "because": "Sichert Funktion"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Kein Updatefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Updates immer automatisch installiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Optionen existieren"}, {"text": "Ja", "correct": false, "because": "Automatisierung optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Updates für alle Softwarearten nötig?', 3, '[{"text": "Ja", "correct": true, "because": "Sicherheit und Stabilität betreffen alle"}, {"text": "Nein", "correct": false, "because": "Breite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Anwendung von Updates?', 4, '[{"text": "Schließen einer bekannten Sicherheitslücke", "correct": true, "because": "Typische Update-Aufgabe"}, {"text": "Erstellen eines Logos", "correct": false, "because": "Gestalterische Aufgabe"}, {"text": "Hardwareinstallation", "correct": false, "because": "Physikalische Aufgabe"}]');
